#!/usr/bin/env node

import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { 
  CallToolRequestSchema,
  ListToolsRequestSchema,
} from '@modelcontextprotocol/sdk/types.js';

import { searchComponents } from './src/tools/searchComponents.js';
import { getComponent } from './src/tools/getComponent.js';
import { listCategories } from './src/tools/listCategories.js';
import { getDemo } from './src/tools/getDemo.js';
import { getInstallGuide } from './src/tools/getInstallGuide.js';
import { previewComponent } from './src/tools/previewComponent.js';
import { analyzeFrontendCode } from './src/tools/analyzeFrontendCode.js';
import { recommendAnimations } from './src/tools/recommendAnimations.js';
import { generateIntegrationCode } from './src/tools/generateIntegrationCode.js';
import { optimizeFrontendWithAnimations } from './src/tools/optimizeFrontendWithAnimations.js';
import { initializeData } from './src/utils/dataLoader.js';
import { initializeJsonData } from './src/utils/jsonDataLoader.js';

class ReactBitsMCPServer {
  constructor() {
    this.server = new Server(
      {
        name: 'react-bits-mcp',
        version: '1.0.0',
      },
      {
        capabilities: {
          tools: {},
        },
      }
    );

    this.setupToolHandlers();
    this.setupErrorHandling();
  }

  setupToolHandlers() {
    // List available tools
    this.server.setRequestHandler(ListToolsRequestSchema, async () => ({
      tools: [
        {
          name: 'search-react-bits-components',
          description: 'Search for React Bits components by name, category, or functionality',
          inputSchema: {
            type: 'object',
            properties: {
              query: {
                type: 'string',
                description: 'Search query (component name, functionality, etc.)'
              },
              category: {
                type: 'string',
                enum: ['animations', 'text-animations', 'components', 'backgrounds'],
                description: 'Filter by component category'
              },
              techStack: {
                type: 'string',
                enum: ['js-css', 'js-tailwind', 'ts-css', 'ts-tailwind'],
                description: 'Preferred technology stack'
              },
              limit: {
                type: 'number',
                description: 'Maximum number of results to return',
                default: 10
              }
            }
          }
        },
        {
          name: 'get-react-bits-component',
          description: 'Get complete code and documentation for a specific React Bits component',
          inputSchema: {
            type: 'object',
            properties: {
              componentName: {
                type: 'string',
                description: 'Name of the component to retrieve'
              },
              version: {
                type: 'string',
                enum: ['js-css', 'js-tailwind', 'ts-css', 'ts-tailwind'],
                description: 'Component version/tech stack',
                default: 'js-css'
              },
              includeDemo: {
                type: 'boolean',
                description: 'Include demo code',
                default: true
              }
            },
            required: ['componentName']
          }
        },
        {
          name: 'list-react-bits-categories',
          description: 'List all available component categories and their statistics',
          inputSchema: {
            type: 'object',
            properties: {
              detailed: {
                type: 'boolean',
                description: 'Include detailed component counts and descriptions',
                default: false
              }
            }
          }
        },
        {
          name: 'get-react-bits-demo',
          description: 'Get demo code and usage examples for a component',
          inputSchema: {
            type: 'object',
            properties: {
              componentName: {
                type: 'string',
                description: 'Name of the component'
              },
              version: {
                type: 'string',
                enum: ['js-css', 'js-tailwind', 'ts-css', 'ts-tailwind'],
                description: 'Component version',
                default: 'js-css'
              }
            },
            required: ['componentName']
          }
        },
        {
          name: 'get-react-bits-install-guide',
          description: 'Get installation and setup guide for a component',
          inputSchema: {
            type: 'object',
            properties: {
              componentName: {
                type: 'string',
                description: 'Name of the component'
              },
              projectType: {
                type: 'string',
                enum: ['vite', 'nextjs', 'cra', 'remix'],
                description: 'Type of React project',
                default: 'vite'
              },
              techStack: {
                type: 'string',
                enum: ['js-css', 'js-tailwind', 'ts-css', 'ts-tailwind'],
                description: 'Technology stack',
                default: 'js-css'
              }
            },
            required: ['componentName']
          }
        },
        {
          name: 'preview-react-bits-component',
          description: 'Get component preview information and basic usage',
          inputSchema: {
            type: 'object',
            properties: {
              componentName: {
                type: 'string',
                description: 'Name of the component'
              }
            },
            required: ['componentName']
          }
        },
        {
          name: 'analyze-frontend-code',
          description: 'Analyze frontend code structure and identify opportunities for animation enhancements',
          inputSchema: {
            type: 'object',
            properties: {
              code: {
                type: 'string',
                description: 'Frontend code to analyze (HTML, CSS, JSX, etc.)'
              },
              framework: {
                type: 'string',
                enum: ['react', 'vue', 'angular', 'vanilla'],
                description: 'Frontend framework being used',
                default: 'react'
              },
              codeType: {
                type: 'string',
                enum: ['component', 'page', 'layout', 'partial'],
                description: 'Type of code being analyzed',
                default: 'component'
              }
            },
            required: ['code']
          }
        },
        {
          name: 'recommend-animations',
          description: 'Recommend suitable animation components based on user requirements and code context',
          inputSchema: {
            type: 'object',
            properties: {
              requirement: {
                type: 'string',
                description: 'User requirement in natural language (e.g., "add loading animation", "make cards more interactive")'
              },
              codeContext: {
                type: 'string',
                description: 'Context about the code structure (optional)'
              },
              priority: {
                type: 'string',
                enum: ['performance', 'visual-impact', 'user-experience', 'simplicity'],
                description: 'Priority for recommendations',
                default: 'user-experience'
              },
              techStack: {
                type: 'string',
                enum: ['js-css', 'js-tailwind', 'ts-css', 'ts-tailwind'],
                description: 'Preferred technology stack',
                default: 'js-css'
              }
            },
            required: ['requirement']
          }
        },
        {
          name: 'generate-integration-code',
          description: 'Generate code to integrate React Bits components into existing frontend code',
          inputSchema: {
            type: 'object',
            properties: {
              originalCode: {
                type: 'string',
                description: 'Original frontend code'
              },
              componentName: {
                type: 'string',
                description: 'React Bits component to integrate'
              },
              integrationPoints: {
                type: 'array',
                items: {
                  type: 'string'
                },
                description: 'Specific points in code where animation should be added'
              },
              techStack: {
                type: 'string',
                enum: ['js-css', 'js-tailwind', 'ts-css', 'ts-tailwind'],
                description: 'Technology stack to use',
                default: 'js-css'
              }
            },
            required: ['originalCode', 'componentName']
          }
        },
        {
          name: 'optimize-frontend-with-animations',
          description: 'Comprehensive tool to analyze code and provide complete animation optimization recommendations',
          inputSchema: {
            type: 'object',
            properties: {
              code: {
                type: 'string',
                description: 'Frontend code to optimize'
              },
              userRequest: {
                type: 'string',
                description: 'User request in natural language (e.g., "make my frontend more engaging", "add loading animations")'
              },
              framework: {
                type: 'string',
                enum: ['react', 'vue', 'angular', 'vanilla'],
                description: 'Frontend framework',
                default: 'react'
              },
              techStack: {
                type: 'string',
                enum: ['js-css', 'js-tailwind', 'ts-css', 'ts-tailwind'],
                description: 'Preferred technology stack',
                default: 'js-css'
              },
              budget: {
                type: 'string',
                enum: ['minimal', 'moderate', 'extensive'],
                description: 'Animation complexity budget',
                default: 'moderate'
              }
            },
            required: ['code', 'userRequest']
          }
        }
      ]
    }));

    // Handle tool calls
    this.server.setRequestHandler(CallToolRequestSchema, async (request) => {
      const { name, arguments: args } = request.params;

      try {
        switch (name) {
          case 'search-react-bits-components':
            return await searchComponents(args);
          
          case 'get-react-bits-component':
            return await getComponent(args);
          
          case 'list-react-bits-categories':
            return await listCategories(args);
          
          case 'get-react-bits-demo':
            return await getDemo(args);
          
          case 'get-react-bits-install-guide':
            return await getInstallGuide(args);
          
          case 'preview-react-bits-component':
            return await previewComponent(args);

          case 'analyze-frontend-code':
            return await analyzeFrontendCode(args);

          case 'recommend-animations':
            return await recommendAnimations(args);

          case 'generate-integration-code':
            return await generateIntegrationCode(args);

          case 'optimize-frontend-with-animations':
            return await optimizeFrontendWithAnimations(args);

          default:
            throw new Error(`Unknown tool: ${name}`);
        }
      } catch (error) {
        return {
          content: [
            {
              type: 'text',
              text: `Error: ${error.message}`
            }
          ],
          isError: true
        };
      }
    });
  }

  setupErrorHandling() {
    this.server.onerror = (error) => {
      console.error('[MCP Error]', error);
    };

    process.on('SIGINT', async () => {
      await this.server.close();
      process.exit(0);
    });
  }

  async run() {
    try {
      // Initialize both data sources
      console.error('Initializing React Bits component data...');
      
      // Initialize JSON data (primary source)
      await initializeJsonData();
      
      // Initialize legacy data loader as fallback
      try {
        await initializeData();
      } catch (error) {
        console.error('Warning: Legacy data loader failed, using JSON data only:', error.message);
      }
      
      console.error('React Bits MCP server ready!');

      const transport = new StdioServerTransport();
      await this.server.connect(transport);
    } catch (error) {
      console.error('Failed to initialize MCP server:', error);
      process.exit(1);
    }
  }
}

// Start the server
const server = new ReactBitsMCPServer();
server.run().catch(console.error);
